  const wtd = all.reduce((a, p) => a + p.value * (p.fit || 60) / 100 * Math.min(1, p.stage / 10), 0), COLM = [['RFQ & intelligence', 1, 3], ['Bid / no-bid', 4, 4], ['Design, capacity & price', 5, 7], ['Offer', 8, 8], ['Negotiation & order', 9, 10], ['Build, ship & close-out', 11, 14]];
